const context = $('Nexus Runtime Context').first().json || {};
const setup = context.setup || {};
const event = context.event || {};
const request = context.request || {};
const customer = context.customer || {};
const system = context.system || {};

const text = (value, fallback = '') => {
  const normalized = String(value ?? '').trim();
  return normalized || fallback;
};
const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('\"', '&quot;')
  .replaceAll("'", '&#039;');

const businessName = text(setup.business_name, text(customer.company, 'Webhook customer'));
const message = text(setup.event_message, text(request?.customer?.message, text(request.message, 'No message supplied')));
const externalCustomerId = text(setup.external_customer_id, text(request?.customer?.id, text(request.customer_id, 'not supplied')));
const priority = text(setup.event_priority, text(request?.customer?.priority, text(request.priority, text(setup.default_priority, 'normal'))));
const replyPrefix = text(setup.reply_prefix, 'Webhook request processed');
const eventId = text(event.id, text(system.idempotency_key, 'technical-test'));
const eventType = text(event.type, text(request.event, 'external.request'));
const receivedAt = text(event.received_at, new Date().toISOString());

const title = `${replyPrefix}: ${businessName}`;
const summary = `Processed ${eventType} for customer ${externalCustomerId} with ${priority} priority.`;
const contentHtml = `<section style="font-family:Arial,sans-serif;color:#172033;line-height:1.6">
  <div style="padding:22px;border-radius:16px;background:linear-gradient(135deg,#eef6ff,#f7fbff);border:1px solid #cfe1f7">
    <p style="margin:0 0 8px;color:#2f65a7;font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase">Nexus webhook acceptance output</p>
    <h1 style="margin:0 0 8px;font-size:25px;color:#14263f">${escapeHtml(title)}</h1>
    <p style="margin:0;color:#52657e">${escapeHtml(summary)}</p>
  </div>
  <table style="width:100%;margin-top:18px;border-collapse:collapse">
    <tr><td style="padding:10px;border-bottom:1px solid #e4eaf1;font-weight:700">Event ID</td><td style="padding:10px;border-bottom:1px solid #e4eaf1">${escapeHtml(eventId)}</td></tr>
    <tr><td style="padding:10px;border-bottom:1px solid #e4eaf1;font-weight:700">Event type</td><td style="padding:10px;border-bottom:1px solid #e4eaf1">${escapeHtml(eventType)}</td></tr>
    <tr><td style="padding:10px;border-bottom:1px solid #e4eaf1;font-weight:700">External customer</td><td style="padding:10px;border-bottom:1px solid #e4eaf1">${escapeHtml(externalCustomerId)}</td></tr>
    <tr><td style="padding:10px;border-bottom:1px solid #e4eaf1;font-weight:700">Priority</td><td style="padding:10px;border-bottom:1px solid #e4eaf1">${escapeHtml(priority)}</td></tr>
    <tr><td style="padding:10px;border-bottom:1px solid #e4eaf1;font-weight:700">Received</td><td style="padding:10px;border-bottom:1px solid #e4eaf1">${escapeHtml(receivedAt)}</td></tr>
  </table>
  <div style="margin-top:18px;padding:16px;border-left:4px solid #2563eb;background:#f6f9fd"><strong>Customer message</strong><p style="margin:8px 0 0">${escapeHtml(message)}</p></div>
</section>`;

return [{ json: {
  title,
  summary,
  content_html: contentHtml,
  output_type: 'report',
  event_id: eventId,
  event_type: eventType,
  external_customer_id: externalCustomerId,
  priority,
  processed_at: new Date().toISOString()
} }];
